import React, { useState, useRef, useEffect } from 'react';

const AmbientSound = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef(null);
  const [volume, setVolume] = useState(0.2); // مستوى صوت منخفض افتراضياً لعدم الإزعاج

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  useEffect(() => {
    // محاولة التشغيل التلقائي عند فتح الموقع
    const attemptAutoplay = async () => {
      if (audioRef.current) {
        try {
          await audioRef.current.play();
          setIsPlaying(true);
        } catch (error) {
          // إذا منع المتصفح التشغيل التلقائي، ننتظر أول تفاعل (نقرة) من المستخدم
          const enableAudio = () => {
            audioRef.current.play().then(() => setIsPlaying(true)).catch(() => {});
            document.removeEventListener('click', enableAudio);
          };
          document.addEventListener('click', enableAudio);
        }
      }
    };
    attemptAutoplay();
  }, []);

  const togglePlay = () => {
    if (!audioRef.current) return;
    
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      const playPromise = audioRef.current.play();
      if (playPromise !== undefined) {
        playPromise.catch(error => {
          console.log("Audio play prevented:", error);
        });
      }
    }
    setIsPlaying(!isPlaying);
  };

  return (
    <div className="ambient-player position-fixed start-0 bottom-0 m-3 p-2 bg-white rounded-pill shadow-sm d-flex align-items-center fade-in" style={{ zIndex: 1040, border: '1px solid rgba(0,0,0,0.1)' }}>
      <audio ref={audioRef} loop>
        {/* رابط موسيقى هادئة (يمكنك استبداله بأي رابط mp3 مباشر) */}
        <source src="https://cdn.pixabay.com/download/audio/2022/02/07/audio_1808fbf07a.mp3" type="audio/mp3" />
      </audio>
      
      <button 
        className={`btn btn-sm rounded-circle ${isPlaying ? 'btn-success' : 'btn-outline-secondary'} me-2`}
        onClick={togglePlay}
        style={{ width: 32, height: 32, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        title={isPlaying ? "إيقاف الموسيقى" : "تشغيل موسيقى هادئة"}
      >
        {isPlaying ? '🎵' : '🔇'}
      </button>
      
      {isPlaying && (
        <input 
          type="range" 
          min="0" 
          max="1" 
          step="0.05" 
          value={volume} 
          onChange={(e) => setVolume(parseFloat(e.target.value))}
          style={{ width: '60px', cursor: 'pointer' }} 
          className="form-range my-0"
          title="مستوى الصوت"
        />
      )}
      
      {!isPlaying && <span className="small text-muted ms-1 fw-bold" style={{fontSize: '0.75rem', cursor: 'pointer'}} onClick={togglePlay}>موسيقى</span>}
    </div>
  );
};

export default AmbientSound;
